 function compare(otherId){const other=scenarios.find(x=>x.id===otherId&&x.schema===3),targets=targetType==='audience'?other.audiences:other.components,match=targets.find(x=>x.id===T().id),current=pathMetrics(data,S(),T()),then=match?pathMetrics(data,other,match):null;dialog('Compare component plans',`<label>Compare against<select id="cp-compare">${opts(scenarios.filter(x=>x.schema===3&&x.id!==activeId).map(x=>[x.id,x.name]),otherId)}</select></label><h3>${esc(T().name)}</h3>${then?table(['Measure',S().name,other.name],[['Planned coverage',pct(current.planned.coverage),pct(then.planned.coverage)],['Assessed coverage',pct(current.coverage),pct(then.coverage)],['Learner time',time(current.total),time(then.total)],['Unplanned must-have gaps',current.planned.critical,then.planned.critical],['Selected resources',current.ids.join('; '),then.ids.join('; ')]].map(row=>'<tr>'+row.map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join('')):'<p>This component or audience is not present in the other plan.</p>'}${then&&current.rows.map(r=>r.id).sort().join()!==then.rows.map(r=>r.id).sort().join()?'<p>Different applicability: percentages are not directly comparable.</p>':''}<p>Both calculations use loaded catalogue ${data.version}. Saved snapshot versions: ${esc(S().catalogueVersion)} / ${esc(other.catalogueVersion)}.</p>`);}
