 function proposedWorkbookDialog(mode){if(mode==='import')editable();dialog(mode==='export'?'Save internal training to catalogue Excel':'Add internal training from Excel',`<p>${mode==='export'?`Save internal learning from all components in this scenario (${S().components.reduce((n,c)=>n+c.internal.length,0)} assignments) to a separate <strong>Proposed training</strong> tab. Exporting again updates previously saved assignments. Records from other plans and components are retained.`:'Choose a workbook containing a Proposed training tab, then select an item and its destination component.'}</p><label>Catalogue workbook (.xlsx)<input id="cp-proposed-file" type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"></label><p class="inline-note">${mode==='export'?'Download the updated copy and save it as your catalogue workbook. Existing catalogue sheets, assessment evidence and formulas are preserved.':'Importing adds or updates only the selected internal item. It does not change assessed catalogue courses.'}</p>`,button(mode==='export'?'proposed-export-save':'proposed-import-load',mode==='export'?'Create updated Excel copy':'Load proposed training','','primary')+(mode==='import'&&data.proposedTraining?.rows.length?button('proposed-bundled','Browse saved catalogue proposals'):''));}
